fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs >= 1_000_000_000) {
        val seconds = exposureTimeNs / 1_000_000_000
        if (seconds == 1) "1s" else "$seconds s"
    } else if (exposureTimeNs >= 500_000_000) {
        "0.5s"
    } else if (exposureTimeNs >= 200_000_000) {
        "0.2s"
